const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let lang=safeStorage(localStorage,'riwaq-lang')==='en'?'en':'ar',products=[],cart=[],me={admin:false},route=parseRoute(location.hash),selected={weight:250,grind:0,qty:1},notice='',offline=false,token=0,adminProducts=[],orderRequest=null,lastOrder=null;
const fwd=()=>lang==='ar'?' ←':' →',t=(a,e)=>lang==='ar'?a:e,n=p=>p?.[lang==='ar'?'ar':'en']||'',money=c=>new Intl.NumberFormat(lang==='ar'?'ar-SA-u-nu-latn':'en-SA',{minimumFractionDigits:c%100?2:0,maximumFractionDigits:2}).format(c/100)+' '+t('ر.س','SAR'),cats={beans:['حبوب القهوة','Coffee beans'],drip:['أظرف التقطير','Drip bags'],tools:['أدوات التحضير','Brew tools'],gifts:['البوكسات والهدايا','Gifts & boxes']},grinds=[['حبوب كاملة','Whole beans'],['إسبريسو','Espresso'],['ترشيح','Filter'],['فرنش برس','French press']];
const errors={FORBIDDEN:['ليس لديك صلاحية الإدارة.','Admin access denied.'],INVALID_QUANTITY:['الكمية يجب أن تكون عددا صحيحا بين 1 و20.','Quantity must be a whole number from 1 to 20.'],INSUFFICIENT_STOCK:['الكمية المطلوبة تتجاوز المخزون المتاح. حدث السلة وحاول مجددا.','Requested quantity exceeds available stock. Refresh your bag.'],UNKNOWN_VARIANT:['أحد الخيارات لم يعد متوفرا.','A selected variant is no longer available.'],EMPTY_CART:['السلة فارغة.','Your bag is empty.'],VERSION_CONFLICT:['عدلت بيانات المنتج من جلسة أخرى. أعد تحميله قبل الحفظ.','Product changed elsewhere. Reload before saving.'],PROVIDER_NOT_CONFIGURED:['الخدمة غير مفعلة بعد.','Provider not configured.'],INVALID_TRANSITION:['حالة الطلب تغيرت، أو لا تسمح بهذا الإجراء.','Order status changed or action is not allowed.'],RATE_LIMITED:['طلبات كثيرة، حاول بعد دقيقة.','Too many requests. Try again in one minute.'],NOT_FOUND:['الصفحة أو الطلب غير موجود.','Page or order not found.'],ORDER_NOT_SAVED_HERE:['لم نجد هذا الطلب على هذا الجهاز. تظهر الطلبات في المتصفح الذي أنشئت منه.','This order is not saved on this device. Orders appear in the browser they were placed from.'],SERVER_UNAVAILABLE:['تعذر الوصول إلى الخادم. تحقق من الاتصال وحاول مجددا.','Could not reach the server. Check your connection and retry.'],DATABASE_NOT_CONFIGURED:['قاعدة البيانات غير مهيأة. شغل pnpm db:setup ثم أعد التشغيل.','Database not configured. Run pnpm db:setup and restart.'],INVALID_CUSTOMER:['تحقق من بيانات التوصيل وحاول مجددا.','Please check your delivery details.'],REQUEST_CONFLICT:['تغيرت بيانات الطلب. أعد المحاولة.','Order data changed. Please retry.'],INVALID_EVENT:['إجراء دفع غير صالح.','Invalid payment action.'],BAD_ORIGIN:['طلب من مصدر غير موثوق.','Request origin not allowed.']};
