function toast(s,link){let e=$('#toast');e.textContent=s;if(link){let a=document.createElement('a');a.href=link[0];a.textContent=link[1];e.append(' ',a)}e.className='toast';e.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>e.hidden=true,4200)}
async function api(path,{method='GET',body,headers={}}={}){let controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),12000);try{let r=await fetch(path,{method,credentials:'same-origin',headers:{...(body?{'Content-Type':'application/json'}:{}),...headers},body:body?JSON.stringify(body):undefined,signal:controller.signal});let j;try{j=await r.json()}catch{throw new Error('SERVER_UNAVAILABLE')}if(!r.ok)throw new Error(j.error||'SERVER_UNAVAILABLE');return j}catch(e){if(e.name==='AbortError')throw new Error('SERVER_UNAVAILABLE');throw e}finally{clearTimeout(timeout)}}
function save(){safeStorage(localStorage,'riwaq-cart',JSON.stringify(cart));orderRequest=null}
function synchronize(){const r=restoreCart(safeStorage(localStorage,'riwaq-cart'),products);cart=r.lines;safeStorage(localStorage,'riwaq-cart',JSON.stringify(cart));if(r.changed)notice=t('حدثنا سلتك: أزلنا بيانات غير صالحة أو عدلنا كميات حسب التوفر.','Your bag was repaired: invalid items removed or quantities adjusted to stock.')}
async function refreshCatalog(){let r=await api('/api/catalog');products=r.products;offline=false;synchronize()}
function count(){return cart.reduce((s,l)=>s+l.qty,0)}
function findVariant(id){let p=products.find(p=>p.variants.some(v=>v.id===id));return {p,v:p?.variants.find(v=>v.id===id)}}
function thumb(p){return p.image?`<img src="${esc(p.image)}" alt="${esc(n(p))}" loading="lazy" width="300" height="300" class="product-photo">`:art(p,lang)}
function h(){return `${!safeStorage(sessionStorage,'riwaq-banner')?`<div class="announcement">${t('نسخة اختبار · لا توجد مدفوعات حقيقية','Sandbox · No real payments')}<button data-action="banner" aria-label="${t('إغلاق','Close')}">×</button></div>`:''}<header><a class="logo" href="#/">رواق<small>RIWAQ</small></a><nav>${CATEGORIES.map(k=>`<a href="${shopUrl(k)}">${cats[k][lang==='ar'?0:1]}</a>`).join('')}</nav><div class="tools"><button class="plain" data-action="lang" lang="${t('en','ar')}">${t('EN','عربي')}</button><a href="#/shop" class="icon-link" aria-label="${t('بحث في المنتجات','Search products')}"><svg viewBox="0 0 24 24" width="20" height="20" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5" fill="none" stroke="currentColor" stroke-width="2"/><path d="M15.5 15.5 21 21" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg></a><a href="#/account">${t('طلباتي','My orders')}</a><a href="#/cart" class="bag-link" aria-label="${t('السلة','Bag')}: ${count()}">${t('السلة','Bag')}<span class="badge${count()?'':' is-empty'}">${count()}</span></a>${me.admin?`<a href="#/admin">${t('الإدارة','Admin')}</a>`:''}</div></header>`}
function footer(){return `<section class="newsletter"><div><h3>${t('تفاصيل أوضح. اختيار أهدأ.','Clear details. A calmer choice.')}</h3><ul class="perks"><li>${t('شحن مجاني للطلبات من '+money(18000),'Free shipping from '+money(18000))}</li><li>${t('اختر الوزن ودرجة الطحن','Pick your weight and grind')}</li><li>${t('السعر والمخزون يتحقق منهما الخادم','Price and stock verified by the server')}</li></ul></div><a class="btn alt" href="#/shop">${t('اكتشف مجموعتنا','Explore our collection')}${fwd()}</a></section><footer><div class="footer-grid"><div class="logo">رواق<small>RIWAQ</small><p>${t('قهوة تستحق وقتك. علامة وكتالوج تجريبيان.','Coffee worth your time. Fictional brand and catalog.')}</p></div><div><b>${t('اكتشف رواق','Explore RIWAQ')}</b>${[['shop','جميع المنتجات','All products'],['about','حكايتنا','Our story'],['faq','الأسئلة الشائعة','FAQ'],['contact','تواصل معنا','Contact']].map(a=>`<a href="#/${a[0]}">${a[lang==='ar'?1:2]}</a>`).join('')}</div><div><b>${t('قبل أن تطلب','Before ordering')}</b>${[['shipping','الشحن والاسترجاع','Shipping & returns'],['privacy','الخصوصية','Privacy'],['terms','الشروط','Terms'],['launch','عن النسخة التجريبية','About this demo']].map(a=>`<a href="#/${a[0]}">${a[lang==='ar'?1:2]}</a>`).join('')}</div></div><div class="bottom"><span>© 2026 RIWAQ · ${t("نسخة تجريبية للعرض — لا بيع أو تحصيل فعلي","Demo store — no actual sales or payments")}</span>${me.adminAvailable===false?"":`<a href="#/admin">${t("دخول الإدارة","Admin")}</a>`}</div></footer>`}
function card(p,v=p.variants.find(v=>v.weight===(p.cat==='beans'?250:0)&&v.grind===0)){if(!v)return '';return `<article class="card"><a class="art" href="#/product/${encodeURIComponent(p.id)}?weight=${v.weight}">${thumb(p)}</a><div class="row"><h3><a href="#/product/${encodeURIComponent(p.id)}?weight=${v.weight}">${esc(n(p))}</a></h3>${v.stock===0?`<span class="tag">${t('نفد','Sold out')}</span>`:''}</div><p>${esc(p[lang==='ar'?'notes':'notesEn'])}${v.weight?' · '+(v.weight===1000?t('1 كجم','1 kg'):v.weight+' '+t('جم','g')):''}</p><div class="row"><strong>${money(v.price)}</strong><a href="#/product/${encodeURIComponent(p.id)}?weight=${v.weight}" class="chip" aria-label="${t('تفاصيل','Details')} ${esc(n(p))}">↗</a></div></article>`}
const welcomeLines=[['صباحك ثقيل؟ <em>خلّه على رواق</em>','Heavy morning? <em>Leave it to Riwaq</em>'],['محاصيل مختصة <em>من أصلها لفنجالك</em>','Specialty origins, <em>straight to your cup</em>'],['أظرف تقطير <em>قهوتك وين ما كنت</em>','Drip bags: <em>your coffee, anywhere</em>'],['اختر وزنك <em>وطحنتك على ذوقك</em>','Your weight, <em>your grind, your way</em>'],['هديتك جاهزة <em>بوكسات رواق</em>','Gifting made easy: <em>Riwaq boxes</em>'],['تبي تغيّر جو؟ <em>جرّب محصول جديد</em>','Need a change? <em>Try a new origin</em>']];
let welcomeIndex=Math.floor(Math.random()*welcomeLines.length),welcomeTimer=0,welcomePaused=false,saduSvg=null;
const reduceMotion=matchMedia('(prefers-reduced-motion: reduce)'),SADU_URL=encodeURI('/patterns/شريط_زخرفة_السدو.svg'),SADU_TILES=10;
function welcome(){return `<section class="welcome" aria-label="${t('ترحيب','Welcome')}"><div class="sadu-band" aria-hidden="true"></div><div class="welcome-stage">${welcomeLines.map((l,i)=>`<p class="welcome-line${i===welcomeIndex?' is-active':''}"${i===welcomeIndex?'':' aria-hidden="true"'}>${l[lang==='ar'?0:1]}</p>`).join('')}</div><div class="sadu-band" aria-hidden="true"></div></section>`}
function loadSadu(){return saduSvg??=fetch(SADU_URL).then(r=>{if(!r.ok)throw new Error('SADU_MISSING');return r.text()}).then(text=>{let svg=new DOMParser().parseFromString(text,'image/svg+xml').documentElement;if(svg.nodeName!=='svg')throw new Error('SADU_INVALID');svg.querySelector('title')?.remove();svg.querySelectorAll('[id]').forEach(e=>e.removeAttribute('id'));svg.setAttribute('viewBox','79.4 173.3 1600 193.4');svg.removeAttribute('width');svg.removeAttribute('height');svg.setAttribute('focusable','false');return svg}).catch(()=>{saduSvg=null;return null})}
function stepWelcome(){let lines=[...document.querySelectorAll('.welcome-line')];if(!lines.length)return stopWelcome();if(document.hidden||document.querySelector('.welcome:hover,.welcome:focus-within'))return;let prev=lines[welcomeIndex];prev.classList.replace('is-active','is-leaving');prev.setAttribute('aria-hidden','true');setTimeout(()=>prev.classList.remove('is-leaving'),800);welcomeIndex=(welcomeIndex+1)%lines.length;lines[welcomeIndex].classList.add('is-active');lines[welcomeIndex].removeAttribute('aria-hidden')}
function stopWelcome(){clearInterval(welcomeTimer);welcomeTimer=0}
function startWelcome(){stopWelcome();if(!reduceMotion.matches&&!welcomePaused&&document.querySelector('.welcome'))welcomeTimer=setInterval(stepWelcome,3600)}
function mountWelcome(active){stopWelcome();if(!active)return;loadSadu().then(svg=>{if(svg)document.querySelectorAll('.sadu-band:empty').forEach(b=>{for(let i=0;i<SADU_TILES;i++)b.append(svg.cloneNode(true))})});startWelcome()}
reduceMotion.addEventListener?.('change',startWelcome);
function home(){let featured=listing(products,'beans',{sort:'newest'}).sort((a,b)=>(b.variant.stock>0)-(a.variant.stock>0)).slice(0,4),giftArt=products.find(p=>p.cat==='gifts');return `${welcome()}<section class="hero"><div class="hero-copy"><span class="eyebrow">RIWAQ SPECIALTY COFFEE</span><h1>${t('لكل يوم رواق.<br>ولكل رواق قهوة.','Find your pause.<br>Find your coffee.')}</h1><p>${t('محاصيل مختارة، وطقوس بسيطة. اكتشف القهوة التي تشبه ذائقتك، وخذ للحظة حقها من الهدوء.','Thoughtful origins. Simple rituals. Discover your coffee and make room for the moment.')}</p><a class="btn" href="#/shop">${t('اكتشف قهوتك','Discover your coffee')}${fwd()}</a><button class="plain" data-action="quiz">${t('ساعدني أختار','Help me choose')}</button></div><div class="hero-art"><div class="stamp">${t('لحظتك<br>على مهل','YOUR DAILY<br>RITUAL')}</div>${products[0]?thumb(products[0]):''}</div></section><div class="strip"><span>${t('تفاصيل المحصول واضحة','Clear origin details')}</span><span>${t('اختر الوزن والطحن','Choose weight and grind')}</span><span>${t('اقتراح يناسب ذائقتك','Find your flavour')}</span></div><section class="wrap"><div class="section-top"><div><span class="eyebrow">THE COFFEE COLLECTION</span><h2>${t('ابدأ بطعم تحبه','Start with a taste you love')}</h2></div><a href="#/shop">${t('جميع المنتجات','View all')} ↗</a></div><div class="categories">${CATEGORIES.map(k=>`<a class="chip" href="${shopUrl(k)}">${cats[k][lang==='ar'?0:1]}</a>`).join('')}</div><div class="grid">${featured.map(x=>card(x.product,x.variant)).join('')}</div></section><section class="taste"><div class="taste-inner"><div><span class="eyebrow">FIND YOUR FLAVOUR</span><h2>${t('ذائقتك هي الدليل.','Let your taste lead.')}</h2><p>${t('ثلاثة أسئلة تقربك من كوبك المناسب.','Three questions to discover your next cup.')}</p><button class="btn alt" data-action="quiz">${t('اختر قهوتك','Find my coffee')}${fwd()}</button></div><div class="taste-options">${[['شوكولاتية','Chocolatey','◒'],['فاكهية','Fruity','✳'],['متوازنة','Balanced','◐']].map(a=>`<a href="${shopUrl('',{taste:a[0]})}"><span class="taste-symbol">${a[2]}</span>${a[lang==='ar'?0:1]}</a>`).join('')}</div></div></section><section class="wrap story"><div class="drawing" aria-hidden="true">${giftArt?thumb(giftArt):''}<span class="ritual">THE EVERYDAY RITUAL</span></div><div><span class="eyebrow">OUR PHILOSOPHY</span><h2>${t('مساحة صغيرة<br>ليوم أجمل.','A small pause.<br>A better day.')}</h2><p>${t('رواق فكرة تبدأ من لحظة: أن تمنح قهوتك وقتا، وتكتشف ما تحبه حقا.','RIWAQ begins with a moment: time for your coffee and space to discover what you love.')}</p><a href="#/about">${t('حكاية رواق','Our story')}${fwd()}</a></div></section>`}
function selectFilter(k,label,values){return `<select data-filter="${k}" aria-label="${esc(label)}"><option value="">${esc(label)}</option>${values.map(([v,text])=>`<option value="${esc(v)}" ${route.filters[k]===v?'selected':''}>${esc(text)}</option>`).join('')}</select>`}
function shop(){const f=route.filters,cat=route.id||'';return `<section class="wrap"><span class="eyebrow">CURATED FOR YOUR EVERYDAY</span><h1>${cat?cats[cat][lang==='ar'?0:1]:t('اكتشف مجموعتنا','Explore the collection')}</h1><div class="categories"><a class="chip ${!cat?'active':''}" href="${shopUrl('',f)}">${t('الكل','All')}</a>${CATEGORIES.map(k=>`<a class="chip ${cat===k?'active':''}" href="${shopUrl(k,f)}">${cats[k][lang==='ar'?0:1]}</a>`).join('')}</div><div class="filters"><input id="search" type="search" data-filter="q" value="${esc(f.q)}" aria-label="${t('البحث','Search')}" placeholder="${t('ابحث عن محصول أو بلد أو إيحاء','Search origin, name or tasting note')}">${selectFilter('country',t('بلد المنشأ','Origin'),[['إثيوبيا','Ethiopia'],['البرازيل','Brazil'],['كولومبيا','Colombia'],['كينيا','Kenya']].map(a=>[a[0],lang==='ar'?a[0]:a[1]]))}${selectFilter('taste',t('الذائقة','Taste'),[['شوكولاتية','Chocolatey'],['فاكهية','Fruity'],['متوازنة','Balanced']].map(a=>[a[0],lang==='ar'?a[0]:a[1]]))}${selectFilter('brew',t('التحضير','Brew'),[['ترشيح','Filter'],['إسبريسو','Espresso'],['فرنش برس','French press']].map(a=>[a[0],lang==='ar'?a[0]:a[1]]))}${selectFilter('weight',t('الوزن','Weight'),[['250',t('250 جم','250 g')],['500',t('500 جم','500 g')],['1000',t('1 كجم','1 kg')]])}${selectFilter('price',t('السعر','Price'),['6000','10000','20000'].map(v=>[v,t('حتى ','Up to ')+money(+v)]))}<select data-filter="sort" aria-label="${t('الترتيب','Sort')}">${[['newest',t('الأحدث','Newest')],['asc',t('السعر: الأقل','Price: low to high')],['desc',t('السعر: الأعلى','Price: high to low')]].map(a=>`<option value="${a[0]}" ${f.sort===a[0]?'selected':''}>${a[1]}</option>`).join('')}</select><button class="plain" data-action="reset-filters">${t('مسح الفلاتر','Reset filters')}</button></div><p class="demo">${t('عند اختيار وزن، تعرض النتائج الخيارات المتوفرة وسعر الوزن المختار.','Selecting a weight shows available variants and their matching prices.')}</p><p id="result-count" class="demo" role="status"></p><div id="results" class="grid"></div></section>`}
function updateResults(){let list=listing(products,route.id,route.filters);$('#result-count').textContent=t(`${list.length} منتجا`,`${list.length} products`);$('#results').innerHTML=list.length?list.map(x=>card(x.product,x.variant)).join(''):`<div class="empty span-all"><h2>${t('ما لقينا تطابقا.','No matches found.')}</h2><button class="btn" data-action="reset-filters">${t('مسح الفلاتر','Reset filters')}</button></div>`}
function variant(p){return p.variants.find(v=>v.active&&v.weight===(p.cat==='beans'?selected.weight:0)&&v.grind===(p.cat==='beans'?selected.grind:0))}
function productPage(p){let v=variant(p),ok=v&&v.stock>0;return `<section class="wrap"><div class="breadcrumbs"><a href="#/shop">${t('المجموعة','Collection')}</a> / ${esc(n(p))}</div><div class="detail"><div><div class="detail-art">${thumb(p)}</div><p class="demo">${t('صورة أو رسم توضيحي للمنتج التجريبي.','Illustrative image for a demo product.')}</p></div><div class="details"><span class="eyebrow">${cats[p.cat][lang==='ar'?0:1]}</span><h1>${esc(n(p))}</h1><p>${esc(p[lang==='ar'?'notes':'notesEn'])}</p><h2>${v?money(v.price):t('غير متوفر','Unavailable')}</h2>${p.cat==='beans'?`<label>${t('الوزن','Weight')}</label><div class="options">${[250,500,1000].map(w=>`<button class="chip" data-action="weight" data-value="${w}" aria-pressed="${selected.weight===w}">${w===1000?t('1 كجم','1 kg'):w+' '+t('جم','g')}</button>`).join('')}</div><label>${t('الطحن','Grind')}</label><div class="options">${grinds.map((g,i)=>`<button class="chip" data-action="grind" data-value="${i}" aria-pressed="${selected.grind===i}">${g[lang==='ar'?0:1]}</button>`).join('')}</div>`:''}<div class="row purchase"><label>${t('الكمية','Quantity')}<input id="product-qty" aria-label="${t('الكمية','Quantity')}" type="number" min="1" step="1" max="${Math.min(20,v?.stock||0)}" value="${selected.qty}"></label><button class="btn" data-action="add" data-id="${esc(p.id)}" ${ok?'':'disabled'}>${ok?t('أضف إلى السلة','Add to bag'):t('غير متوفر لهذا الخيار','Unavailable selection')}</button></div><p class="error" id="qty-error" role="alert"></p><p class="demo">${t('التوفر والسعر يتحقق منهما الخادم عند الطلب.','Price and availability are verified by the server at checkout.')}</p><div class="specs">${[[t('المنشأ','Origin'),p[lang==='ar'?'country':'countryEn']],[t('المنطقة','Region'),p[lang==='ar'?'region':'regionEn']],[t('المعالجة','Process'),p[lang==='ar'?'process':'processEn']],[t('الإيحاءات','Notes'),p[lang==='ar'?'notes':'notesEn']]].filter(a=>a[1]).map(a=>`<div><small>${a[0]}</small>${esc(a[1])}</div>`).join('')}</div><h3>${t('لحظة التحضير','Your brewing ritual')}</h3><p>${t('ابدأ بنسبة 15 جم قهوة إلى 250 مل ماء للترشيح، وعدل حسب ذائقتك.','For filter coffee, start with 15 g to 250 ml water and adjust to taste.')}</p></div></div><h2>${t('اكتشف أيضا','You may also enjoy')}</h2><div class="grid">${products.filter(x=>x.cat===p.cat&&x.id!==p.id).slice(0,4).map(x=>card(x)).join('')}</div></section><div class="mobile-add"><b>${v?money(v.price):''}</b><button class="btn" data-action="add" data-id="${esc(p.id)}" ${ok?'':'disabled'}>${t('أضف إلى السلة','Add to bag')}</button></div>`}
function steps(n){return `<ol class="steps" aria-label="${t('مراحل الطلب','Checkout steps')}">${[[t('السلة','Bag')],[t('بيانات التوصيل','Delivery details')],[t('الدفع التجريبي','Sandbox payment')],[t('التأكيد','Confirmation')]].map((s,i)=>`<li class="${i+1<n?'done':i+1===n?'current':''}"${i+1===n?' aria-current="step"':''}><span>${i+1<n?'✓':i+1}</span>${s[0]}</li>`).join('')}</ol>`}
function shippingHint(subtotal){let left=18000-subtotal;return left>0?`<p class="ship-hint">${t('أضف '+money(left)+' للحصول على شحن مجاني.','Add '+money(left)+' for free shipping.')}</p><div class="ship-bar" aria-hidden="true"><span style="width:${Math.round(subtotal/180)}%"></span></div>`:`<p class="ship-hint ok">${t('طلبك مؤهل للشحن المجاني.','Your order qualifies for free shipping.')}</p>`}
function cartPage(){return `<section class="wrap">${cart.length?steps(1):''}<h1>${t('سلتك، على ذائقتك.','Your bag. Your taste.')}</h1>${cart.length?`${cart.map((l,i)=>{let {p,v}=findVariant(l.variant_id);return `<div class="cart-line">${thumb(p)}<div><h3><a href="#/product/${encodeURIComponent(p.id)}?weight=${v.weight}">${esc(n(p))}</a></h3>${p.cat==='beans'?`<select data-cart="weight" data-index="${i}" aria-label="${t('الوزن','Weight')}">${[250,500,1000].map(w=>`<option value="${w}" ${w===v.weight?'selected':''}>${w} ${t('جم','g')}</option>`).join('')}</select><select data-cart="grind" data-index="${i}" aria-label="${t('الطحن','Grind')}">${grinds.map((g,j)=>`<option value="${j}" ${j===v.grind?'selected':''}>${g[lang==='ar'?0:1]}</option>`).join('')}</select>`:''}<div class="purchase"><input type="number" min="1" max="20" step="1" value="${l.qty}" data-cart="qty" data-index="${i}" aria-label="${t('الكمية','Quantity')}" class="qty"><button class="plain" data-action="remove" data-index="${i}">${t('حذف','Remove')}</button></div></div><b>${money(v.price*l.qty)}</b></div>`}).join('')}<div class="cart-summary">${(q=>shippingHint(q.subtotal)+summary(q))(quote(cart,products))}<a href="#/checkout" class="btn">${t('متابعة إلى بيانات التوصيل','Continue to delivery details')}${fwd()}</a><a href="#/shop" class="continue">${t('مواصلة التسوق','Continue shopping')}</a></div>`:`<div class="empty"><h2>${t('سلتك تنتظر أول اختيار.','Your bag awaits its first coffee.')}</h2><a href="#/shop" class="btn">${t('تصفح المجموعة','Explore collection')}</a></div>`}</section>`}
function summary(q){return `<div class="row"><span>${t('المنتجات','Subtotal')}</span><b>${money(q.subtotal)}</b></div><div class="row purchase"><span>${t('الشحن التجريبي','Sandbox shipping')}</span><span>${q.shipping?money(q.shipping):t('مجاني','Free')}</span></div><hr><div class="row"><b>${t('الإجمالي','Total')}</b><b>${money(q.total)}</b></div><p class="demo">${t('أسعار اختبار دون تحصيل. إعداد الضرائب والفوترة مطلوب قبل الإطلاق.','Test prices. No payment collected. Tax/invoicing setup required before launch.')}</p>`}
const checkoutFields=()=>[['name',t('الاسم الكامل','Full name'),'text','name',t('مثال: سارة العتيبي','e.g. Sara Alotaibi'),t('اكتب الاسم (حرفان على الأقل).','Enter your name (at least 2 letters).'),'right'],['email',t('البريد الإلكتروني','Email'),'email','email','name@example.com',t('اكتب بريدا إلكترونيا صحيحا.','Enter a valid email address.'),'ltr'],['phone',t('رقم الجوال','Mobile number'),'tel','tel','05XXXXXXXX',t('رقم جوال سعودي يبدأ بـ 05 ويتكون من 10 أرقام.','Saudi mobile: 10 digits starting with 05.'),'ltr'],['city',t('المدينة','City'),'text','address-level2',t('مثال: الرياض','e.g. Riyadh'),t('اكتب اسم المدينة.','Enter your city.'),'right'],['address',t('الحي والشارع','District & street'),'text','street-address',t('مثال: حي العليا، شارع التحلية','e.g. Olaya, Tahlia St.'),t('اكتب الحي والشارع (4 أحرف على الأقل).','Enter district and street (at least 4 characters).'),'right'],['postal',t('الرمز البريدي','Postal code'),'text','postal-code','12345',t('الرمز البريدي 5 أرقام.','Postal code must be 5 digits.'),'ltr']];
function checkoutPage(){if(!cart.length)return cartPage();return `<section class="wrap">${steps(2)}<h1>${t('بيانات التوصيل','Delivery details')}</h1><div class="notice">${t('هذه نسخة تجريبية: لن يتم شحن أي منتج أو خصم أي مبلغ. استخدم بيانات تجريبية فقط. سنحجز الكمية لك 30 دقيقة حتى تكمل الدفع التجريبي.','Demo store: nothing will be shipped or charged. Use test data only. Your items are reserved for 30 minutes while you complete the sandbox payment.')}</div><div class="checkout"><form id="checkout-form" novalidate><button type="button" class="plain fill-demo" data-action="fill-demo">${t('تعبئة بيانات تجريبية','Fill with test data')}</button><div class="formgrid">${checkoutFields().map(a=>`<div class="field"><label for="${a[0]}">${a[1]}</label><input name="${a[0]}" id="${a[0]}" type="${a[2]}" required autocomplete="${a[3]}" placeholder="${esc(a[4])}"${a[6]==='ltr'?' dir="ltr"':''}${a[0]==='postal'?' inputmode="numeric" maxlength="5"':''}${a[0]==='phone'?' inputmode="tel" maxlength="16"':''} aria-describedby="${a[0]}-error"><span id="${a[0]}-error" class="error"></span></div>`).join('')}</div><p class="demo">${t('الدولة: المملكة العربية السعودية','Country: Saudi Arabia')}</p><p class="error" id="checkout-error" role="alert"></p><button class="btn wide" type="submit" id="place-order" disabled>${t('جاري التحقق من السعر...','Verifying price...')}</button><p class="demo">${t('في الخطوة التالية تختار نتيجة الدفع التجريبي. لا توجد بطاقة أو تحصيل حقيقي.','Next you choose a sandbox payment outcome. No real card or charge.')}</p></form><aside class="summary" id="server-quote"><p role="status">${t('جاري التحقق من الخادم...','Checking with server...')}</p></aside></div></section>`}
function orderItems(items){return `<ul class="order-items">${items.map(l=>`<li><span>${esc(lang==='ar'?l.name:(l.en||products.find(p=>p.id===l.product_id)?.en||l.name))}${l.weight?` · ${l.weight===1000?t('1 كجم','1 kg'):l.weight+' '+t('جم','g')} · ${grinds[l.grind]?.[lang==='ar'?0:1]||''}`:''} <small>× ${l.qty}</small></span><b>${money(l.price*l.qty)}</b></li>`).join('')}</ul>`}
async function loadQuote(myToken){try{let q=await api('/api/quote',{method:'POST',body:{lines:cart}});if(myToken!==token)return;$('#server-quote').innerHTML=`<h3>${t('ملخص الطلب','Order summary')}</h3>${orderItems(q.items)}`+summary(q);$('#place-order').disabled=false;$('#place-order').textContent=t('متابعة إلى الدفع التجريبي','Continue to sandbox payment')+' '+t('←','→')}catch(e){if(myToken!==token)return;$('#server-quote').textContent=errorText(e);$('#place-order').textContent=t('غير متاح حاليا','Currently unavailable')}}
function validateForm(f){let checks={name:v=>v.trim().length>=2&&v.length<=100,email:v=>/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v)&&v.length<=150,phone:v=>/^(05\d{8}|\+9665\d{8}|9665\d{8})$/.test(v.replace(/\s/g,'')),city:v=>v.trim().length>=2,address:v=>v.trim().length>=4,postal:v=>/^\d{5}$/.test(v)},ok=true,data={};for(let[k,check]of Object.entries(checks)){data[k]=f.elements[k].value;let valid=check(data[k]);f.elements[k].setAttribute('aria-invalid',!valid);$('#'+k+'-error').textContent=valid?'':checkoutFields().find(x=>x[0]===k)[5];if(!valid)ok=false}if(!ok)f.querySelector('[aria-invalid=true]').focus();return ok?data:null}
async function placeOrder(f){let customer=validateForm(f);if(!customer)return;let b=$('#place-order');b.disabled=true;$('#checkout-error').textContent='';try{let signature=JSON.stringify({customer,cart});if(!orderRequest||orderRequest.signature!==signature)orderRequest={signature,request_key:randomId(),order_token:randomId()};let r=await api('/api/orders',{method:'POST',body:{customer,lines:cart,request_key:orderRequest.request_key,order_token:orderRequest.order_token}});rememberOrder(r.id,orderRequest.order_token);cart=[];save();location.hash='/order/'+r.id}catch(e){$('#checkout-error').textContent=errorText(e);b.disabled=false;if(e.message==='INSUFFICIENT_STOCK')toast(t('ارجع للسلة لتحديث المخزون.','Return to your bag to update availability.'))}}
function orderTokens(){try{let v=JSON.parse(safeStorage(localStorage,'riwaq-orders')||'[]');return Array.isArray(v)?v.filter(o=>o&&/^[0-9a-f-]{36}$/.test(o.id)&&typeof o.token==='string'):[]}catch{return []}}
function rememberOrder(id,orderTok){let list=orderTokens().filter(o=>o.id!==id);list.unshift({id,token:orderTok,at:Date.now()});safeStorage(localStorage,'riwaq-orders',JSON.stringify(list.slice(0,20)))}
function orderToken(id){return orderTokens().find(o=>o.id===id)?.token||safeStorage(sessionStorage,'riwaq-order-'+id)}
const shortRef=id=>'RWQ-'+String(id).slice(0,8).toUpperCase(),when=s=>new Intl.DateTimeFormat(lang==='ar'?'ar-SA-u-nu-latn-ca-gregory':'en-GB',{dateStyle:'medium',timeStyle:'short'}).format(new Date(s*1000));
function statusName(s){let m={pending:['بانتظار الدفع التجريبي','Awaiting sandbox payment'],paid:['مؤكد · دفع تجريبي','Confirmed · sandbox payment'],payment_failed:['فشل دفع تجريبي','Sandbox payment failed'],cancelled:['ملغي','Cancelled'],expired:['انتهى الحجز','Reservation expired'],refunded:['مسترد تجريبيا','Sandbox refunded']};return m[s]?.[lang==='ar'?0:1]||s}
function payPanel(o){return `<div class="pay-panel"><div class="pay-head"><h2>${t('بوابة الدفع التجريبية','Sandbox payment gateway')}</h2><span class="sandbox-badge">${t('محاكاة','SIMULATION')}</span></div><p>${t('لا نطلب أي بيانات بطاقة، ولن يُخصم أي مبلغ. اختر نتيجة الدفع لتجربة رحلة العميل كاملة.','No card details are requested and nothing is charged. Choose a payment outcome to try the full customer journey.')}</p><fieldset class="pay-methods"><legend>${t('طريقة الدفع (للعرض فقط)','Payment method (display only)')}</legend>${[['mada','مدى','mada'],['card','بطاقة ائتمانية','Credit card'],['apple','Apple Pay','Apple Pay']].map((m,i)=>`<label><input type="radio" name="pay-method" value="${m[0]}" ${i?'':'checked'}> ${lang==='ar'?m[1]:m[2]}</label>`).join('')}</fieldset><div class="pay-total"><span>${t('المبلغ','Amount')}</span><b>${money(o.total)}</b></div><button class="btn wide" data-action="sandbox-pay" data-outcome="paid">${t('إتمام الدفع التجريبي','Complete sandbox payment')}</button><button class="plain fail-link" data-action="sandbox-pay" data-outcome="failed">${t('محاكاة فشل الدفع','Simulate a failed payment')}</button><p class="demo">${t('الكمية محجوزة لك حتى','Items reserved until')} ${esc(when(o.expires_at))}</p></div>`}
async function orderPage(id,myToken){try{let tok=orderToken(id);if(!tok)throw new Error('ORDER_NOT_SAVED_HERE');let o=await api('/api/orders/'+encodeURIComponent(id),{headers:{'x-order-token':tok}});if(myToken!==token)return;lastOrder=o;let s=o.status,head={pending:[t('خطوة أخيرة: الدفع التجريبي','One last step: sandbox payment'),''],paid:[t('شكرا لك! تم تأكيد طلبك','Thank you! Your order is confirmed'),t('هذا طلب تجريبي: لم يُخصم أي مبلغ ولن يتم شحن أي منتج.','This is a demo order: nothing was charged and nothing will ship.')],payment_failed:[t('لم يكتمل الدفع التجريبي','The sandbox payment did not go through'),t('اخترت محاكاة فشل الدفع. أعيدت الكمية للمخزون، ويمكنك المحاولة بطلب جديد.','You simulated a failed payment. Items were released; you can retry with a new order.')],cancelled:[t('تم إلغاء الطلب','Order cancelled'),t('أعيدت الكمية للمخزون.','Items were returned to stock.')],expired:[t('انتهت مهلة حجز الطلب','Reservation expired'),t('مرت 30 دقيقة دون إتمام الدفع، فأعيدت الكمية للمخزون.','30 minutes passed without payment, so items were released.')],refunded:[t('تم استرداد الطلب تجريبيا','Order refunded (sandbox)'),'']}[s]||[statusName(s),''];$('#main').innerHTML=`<section class="wrap">${steps(s==='paid'?5:s==='pending'?3:4)}<div class="order-layout"><div><span class="eyebrow">${t('طلب تجريبي','DEMO ORDER')} · ${esc(shortRef(o.id))}</span><h1 class="${s==='paid'?'success-title':''}">${s==='paid'?'<span class="check" aria-hidden="true">✓</span>':''}${head[0]}</h1>${head[1]?`<p class="lead">${head[1]}</p>`:''}${s==='pending'?payPanel(o):''}<div class="order-actions">${['payment_failed','cancelled','expired'].includes(s)?`<button class="btn" data-action="retry-order">${t('إعادة المحاولة بطلب جديد','Retry as new order')}</button>`:''}${s==='paid'?`<a class="btn" href="#/shop">${t('مواصلة التسوق','Continue shopping')}</a><a class="btn alt" href="#/account">${t('طلباتي','My orders')}</a>`:''}${s==='pending'?`<button class="plain" data-action="cancel-order">${t('إلغاء الطلب','Cancel order')}</button>`:''}${s!=='paid'&&s!=='pending'?`<a class="btn alt" href="#/shop">${t('العودة للمتجر','Back to store')}</a>`:''}</div></div><aside class="summary"><h3>${t('تفاصيل الطلب','Order details')}</h3><p class="demo">${t('رقم الطلب','Order no.')} <b dir="ltr">${esc(shortRef(o.id))}</b> · ${esc(when(o.created_at))}</p><p><span class="status-pill s-${esc(s)}">${esc(statusName(s))}</span></p>${orderItems(o.items)}${summary(o)}</aside></div></section>`;if(s==='pending')$('#main [data-action=sandbox-pay]')?.focus({preventScroll:true})}catch(e){if(myToken===token)$('#main').innerHTML=`<section class="wrap empty"><h1>${errorText(e)}</h1><a class="btn" href="#/account">${t('طلباتي','My orders')}</a> <a class="btn alt" href="#/shop">${t('العودة للمتجر','Back to store')}</a></section>`}}
async function accountPage(myToken){let list=orderTokens();if(!list.length){$('#main').innerHTML=`<section class="wrap empty"><h1>${t('لا توجد طلبات بعد','No orders yet')}</h1><p>${t('الطلبات التي تنشئها من هذا المتصفح ستظهر هنا. لا حاجة لإنشاء حساب.','Orders you place from this browser will appear here. No account needed.')}</p><a class="btn" href="#/shop">${t('ابدأ التسوق','Start shopping')}</a></section>`;return}let rows=await Promise.all(list.map(x=>api('/api/orders/'+x.id,{headers:{'x-order-token':x.token}}).catch(()=>null)));if(myToken!==token)return;rows=rows.filter(Boolean);$('#main').innerHTML=`<section class="wrap"><h1>${t('طلباتي','My orders')}</h1><p class="demo">${t('طلبات تجريبية محفوظة في هذا المتصفح، بلا حساب.','Demo orders saved in this browser; no account needed.')}</p><div class="orders-list">${rows.map(o=>`<a class="order-row" href="#/order/${o.id}"><span><b dir="ltr">${esc(shortRef(o.id))}</b><small>${esc(when(o.created_at))} · ${o.items.reduce((s,l)=>s+l.qty,0)} ${t('منتج','items')}</small></span><span class="status-pill s-${esc(o.status)}">${esc(statusName(o.status))}</span><b>${money(o.total)}</b></a>`).join('')||`<p>${t('تعذر تحميل الطلبات.','Could not load orders.')}</p>`}</div></section>`}
const texts={about:['حكاية رواق','Our story','علامة افتراضية للقهوة المختصة. تجربة الاختيار تبدأ بتفاصيل واضحة، وتمنح كل كوب وقتا يستحقه. المنتجات والصور والأسعار الحالية للتجربة فقط.','A fictional specialty coffee brand. Clear details and thoughtful choices, with time for every cup. Current products, imagery and prices are for testing.'],contact:['تواصل معنا','Contact','بيانات المنشأة وخدمة العملاء لم تضف بعد. لا توجد أرقام أو وسائل تواصل تجارية مفعلة في هذه النسخة.','Business and customer service details have not been configured. No commercial contact channels are active.'],shipping:['الشحن والاسترجاع','Shipping & returns','مسودة للمراجعة. الشحن المحسوب تجريبي: 20 ريالا ومجاني من 180 ريالا. لا توجد شحنات فعلية. يجب تحديد التغطية والمدد وشروط الاسترجاع واعتمادها قبل البيع.','Draft for review. Sandbox shipping is 20 SAR, free from 180 SAR. No actual delivery. Coverage, timelines and returns must be approved before sales.'],privacy:['الخصوصية','Privacy','مسودة للمراجعة: السلة واللغة تحفظان على جهازك. عند حفظ طلب اختبار، تخزن بيانات النموذج في قاعدة بيانات المتجر، ويطلع عليها المسؤول المخول. لا توجد خدمة بريد أو مشاركة مع مزود دفع أو شحن. استخدم بيانات اختبار فقط. يجب اعتماد سياسة الاحتفاظ والحذف وحقوق المستخدم قبل الإطلاق.','Draft: language and bag are stored on your device. Sandbox order submissions are stored in the store database and visible to authorized administrators. No email, payment or shipping provider is connected. Use test data only. Retention, deletion and user rights need approval before launch.'],terms:['الشروط','Terms','نسخة اختبار بلا مبيعات أو تحصيل. الطلبات وأحداث الدفع المعروضة تجريبية. يلزم اعتماد شروط البيع والأسعار والضرائب والتوصيل وبيانات المنشأة قبل الإطلاق.','Sandbox without actual sales or payments. Orders and payment events are test-only. Business details, pricing, tax, delivery and sales terms require approval before launch.'],account:['حسابي','My account','يمكن إتمام نموذج الطلب التجريبي دون إنشاء حساب متجر. دخول الإدارة يعتمد على هوية ChatGPT والتحقق من الصلاحية على الخادم. المعاينة الحالية خاصة بصاحبها.','Sandbox checkout requires no store account. Admin access uses ChatGPT identity and server authorization. The current preview is owner-private.'],launch:['عن النسخة التجريبية وجاهزية الإطلاق','About this demo & launch readiness','تمت إضافة قاعدة بيانات للمنتجات والمخزون والطلبات والعملاء وسجل الإدارة، والتحقق من الأسعار على الخادم وحجز المخزون. الدفع والشحن والرسائل والضرائب والفوترة ليست مفعلة. هذه بيئة اختبار فقط. يتطلب البيع الفعلي حسابات المزودين ومفاتيحهم وبيانات المنشأة وصورا وكتالوجا حقيقيين وسياسات معتمدة واختبارات تكامل ومراجعة أمان.','Database-backed catalog, inventory, orders, customers and audit trail, with server pricing and stock reservations. Payment, shipping, messaging, tax and invoicing are not enabled. Sandbox only. Live launch needs provider accounts and keys, business details, real catalog assets, approved policies, integration tests and security review.']};
function copyPage(k){if(k==='404')return `<section class="wrap empty"><h1>${t('الصفحة غير موجودة','Page not found')}</h1><a class="btn" href="#/shop">${t('العودة للمجموعة','Back to collection')}</a></section>`;if(k==='faq')return `<section class="wrap page-copy"><h1>${t('قبل أول رشفة','Before your first sip')}</h1>${[[t('هل يوجد شراء فعلي؟','Can I place a real order?'),t('لا، تحفظ طلبات اختبار دون دفع أو شحن.','No. Sandbox orders are saved without payment or shipping.')],[t('متى ينتهي حجز المخزون؟','When does stock reservation expire?'),t('بعد 30 دقيقة للطلب غير المكتمل، ويحدث التحرير عند أول طلب للخادم بعد الانتهاء.','After 30 minutes for incomplete orders. Release happens on the next server request.')],[t('كيف أختار الطحن؟','Which grind should I choose?'),t('حبوب كاملة إذا لديك طاحونة، وإلا اختر طريقة التحضير المناسبة.','Choose whole beans if you have a grinder, otherwise select your brewing method.')]].map(a=>`<details><summary>${a[0]}</summary><p>${a[1]}</p></details>`).join('')}</section>`;let a=texts[k]||texts.about;return `<section class="wrap page-copy"><span class="eyebrow">RIWAQ</span><h1>${a[lang==='ar'?0:1]}</h1><p>${a[lang==='ar'?2:3]}</p>${k==='launch'?`<p><a class="btn alt" href="/release-report.txt" download>${t('تنزيل تقرير الإصلاح والجاهزية','Download release report')}</a></p>`:''}${k==='account'&&!me.signedIn?`<a class="btn" href="/signin-with-chatgpt?return_to=%2F%23%2Fadmin" target="_top">${t('دخول الإدارة','Admin sign in')}</a>`:''}</section>`}
async function adminPage(myToken){if(me.adminAvailable===false){$("#main").innerHTML=`<section class="wrap empty"><h1>${t("لوحة الإدارة غير متاحة في هذا الرابط","Admin is not available on this link")}</h1><p>${t("هذه نسخة عرض عامة. لوحة الإدارة تعمل في النسخة المحلية فقط لحماية البيانات.","This is a public demo. The admin panel runs in the local version only, to protect data.")}</p><a class="btn" href="#/shop">${t("العودة للمتجر","Back to store")}</a></section>`;return}if(!me.admin){$('#main').innerHTML=`<section class="wrap"><h1>${t('الإدارة محمية','Protected administration')}</h1><p>${t('يلزم حساب المسؤول المعتمد للدخول.','An authorized administrator account is required.')}</p><a class="btn" target="_top" href="/signin-with-chatgpt?return_to=%2F%23%2Fadmin">${t('تسجيل الدخول','Sign in')}</a></section>`;return}try{let [c,o,a]=await Promise.all([api('/api/admin/catalog'),api('/api/admin/orders'),api('/api/admin/audit')]);if(myToken!==token)return;adminProducts=c.products;$('#main').innerHTML=`<section class="wrap"><h1>${t('إدارة رواق','RIWAQ administration')}</h1><div class="notice">${t('بيئة اختبار. المخزون المعروض هو المتاح بعد الحجوزات. إلغاء الحجز يعيد الكمية. لا تعدل المخزون أثناء الجرد دون مراجعة الطلبات المحجوزة. أحداث الدفع أدناه محاكاة محمية وليست عمليات مالية.','Sandbox. Stock shown is available after reservations. Cancellations restore stock. Review pending reservations before inventory adjustments. Payment events below are protected simulations, not financial transactions.')}</div><a class="btn alt" href="/api/admin/backup" download>${t('تنزيل نسخة احتياطية','Download backup')}</a><button class="btn alt" data-action="admin-refresh">${t('تحديث','Refresh')}</button><h2>${t('إضافة منتج','Add product')}</h2><form id="create-product" class="formgrid"><div class="field"><label for="new-id">ID (a-z, 0-9, -)</label><input id="new-id" name="id" pattern="[-a-z0-9]{3,50}" required></div><div class="field"><label for="new-cat">${t('التصنيف','Category')}</label><select id="new-cat" name="cat">${CATEGORIES.map(k=>`<option value="${k}">${cats[k][lang==='ar'?0:1]}</option>`).join('')}</select></div><div class="field"><label for="new-ar">${t('الاسم العربي','Arabic name')}</label><input id="new-ar" name="ar" required maxlength="100"></div><div class="field"><label for="new-en">${t('الاسم الإنجليزي','English name')}</label><input id="new-en" name="en" required maxlength="100"></div><div class="field"><label for="new-price">${t('السعر الأساسي بالريال','Base price (SAR)')}</label><input id="new-price" name="price" type="number" min="1" step="0.01" required></div><button class="btn">${t('إضافة بمخزون صفر','Create with zero stock')}</button></form><h2>${t('المنتجات والخيارات','Products & variants')}</h2><div class="admin-grid">${c.products.map(p=>adminProduct(p)).join('')}</div><h2>${t('آخر 100 طلب','Latest 100 orders')}</h2>${o.orders.length?o.orders.map(o=>`<article class="admin-item"><p dir="ltr">${esc(o.id)}</p><p>${esc(o.customer.name)} · ${esc(o.customer.email)}</p><p>${esc(statusName(o.status))} · ${money(o.total)}</p><div class="options">${(o.status==='pending'?['paid','failed','cancelled']:o.status==='paid'?['refunded']:[]).map(k=>`<button class="chip" data-action="event" data-id="${esc(o.id)}" data-kind="${k}">${t('اختبار: ','Test: ')}${esc(statusName(k==='failed'?'payment_failed':k))}</button>`).join('')}</div></article>`).join(''):`<p>${t('لا توجد طلبات.','No orders.')}</p>`}<h2>${t('سجل الإدارة','Audit log')}</h2>${a.results.map(a=>`<p class="demo">${esc(new Date(a.created_at*1000).toISOString())} · ${esc(a.action)} · ${esc(a.target)}</p>`).join('')||'<p>—</p>'}</section>`}catch(e){if(myToken===token)$('#main').innerHTML=`<section class="wrap"><h1>${errorText(e)}</h1><button class="btn" data-action="admin-refresh">${t('إعادة المحاولة','Retry')}</button></section>`}}
function adminProduct(p){let groups=[...new Set(p.variants.map(v=>v.inventory_id))];return `<form class="admin-item product-editor" data-id="${esc(p.id)}" data-version="${p.version}"><h3>${esc(n(p))}</h3>${[['ar',t('الاسم العربي','Arabic name')],['en',t('الاسم الإنجليزي','English name')],['notes',t('الإيحاءات بالعربية','Arabic notes')],['notesEn',t('الإيحاءات بالإنجليزية','English notes')],['image',t('رابط صورة HTTPS','HTTPS image URL')]].map(([key,label])=>`<label>${label}<input name="${key}" value="${esc(p[key])}" maxlength="${key==='image'?1000:500}"></label>`).join('')}<label><input type="checkbox" name="active" ${p.active?'checked':''}>${t('منتج ظاهر','Visible product')}</label>${groups.map(key=>{let vs=p.variants.filter(v=>v.inventory_id===key),v=vs[0];return `<fieldset><legend>${v.weight?v.weight+' '+t('جم','g'):t('القطعة','Unit')}</legend><label>${t('المخزون المتاح','Available stock')}<input name="stock:${esc(key)}" type="number" min="0" step="1" value="${v.stock}" required></label><label>${t('السعر بالريال لجميع أنواع الطحن','Price SAR for all grinds')}<input name="price:${esc(key)}" type="number" min="0.01" step="0.01" value="${v.price/100}" required></label></fieldset>`}).join('')}<button class="btn">${t('حفظ التعديلات','Save changes')}</button><p class="error" role="alert"></p></form>`}
let quizState={step:0,answers:[]};function drawQuiz(){let s=quizState.step,qs=[[t('كيف تحضر قهوتك؟','How do you brew?'),['ترشيح','إسبريسو','فرنش برس'],['Filter','Espresso','French press']],[t('ما الذائقة الأقرب لك؟','Preferred taste?'),['شوكولاتية','فاكهية','متوازنة'],['Chocolatey','Fruity','Balanced']],[t('ميزانيتك لكل 250 جم؟','Budget per 250 g?'),['5000','6000','10000'],['50 SAR','60 SAR','100 SAR']]];$('#quiz').innerHTML=`<button class="plain close" data-action="quiz-close" aria-label="${t('إغلاق','Close')}">×</button>`+(s<3?`<span class="eyebrow">${s+1} / 3</span><h2>${qs[s][0]}</h2><div class="quiz-options">${qs[s][1].map((v,i)=>`<button class="chip" data-action="quiz-answer" data-value="${v}">${s===2?t('حتى '+money(+v),'Up to '+money(+v)):lang==='ar'?v:qs[s][2][i]}</button>`).join('')}</div>`:(()=>{let[brew,taste,budget]=quizState.answers,list=products.filter(p=>p.cat==='beans'&&p.variants.some(v=>v.weight===250&&v.grind===0&&v.stock>0&&v.price<=+budget)).sort((a,b)=>(b.taste===taste)*2+(b.brew===brew)-(a.taste===taste)*2-(a.brew===brew));return `<h2>${t('رواقك يبدأ هنا.','Your ritual starts here.')}</h2><p>${t('أقرب اقتراحات حسب التوفر والميزانية.','Closest available matches within budget.')}</p>${list.slice(0,2).map(p=>`<p><a data-action="quiz-close" href="#/product/${encodeURIComponent(p.id)}">${esc(n(p))} ↗</a></p>`).join('')||t('لا يوجد تطابق متوفر. جرب ميزانية أخرى.','No available matches. Try a different budget.')}<button class="btn" data-action="quiz">${t('إعادة الاختيار','Start again')}</button>`})())}
function render({focus=false}={}){let myToken=++token;route=parseRoute(location.hash);document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';let p=products.find(p=>p.id===route.id),page=route.page;if(page==='product'&&!p)page='404';document.body.classList.toggle('has-detail',page==='product');document.title=page==='product'?n(p)+' | RIWAQ':t('رواق | قهوة تستحق وقتك','RIWAQ | Coffee worth your time');let content=offline?`<section class="wrap empty"><h1>${t('تعذر الاتصال بالمتجر','Unable to connect')}</h1><p>${t('تحقق من الاتصال وحاول مجددا. لا يمكن تأكيد الأسعار أو الطلبات الآن.','Check your connection and retry. Prices and orders cannot be verified right now.')}</p><button class="btn" data-action="reload">${t('إعادة المحاولة','Retry')}</button></section>`:page==='home'?home():page==='shop'?shop():page==='product'?productPage(p):page==='cart'?cartPage():page==='checkout'?checkoutPage():['admin','order','account'].includes(page)?`<p class="loading" role="status">${t('جاري التحميل...','Loading...')}</p>`:copyPage(page);$('#app').innerHTML=h()+`<main id="main" tabindex="-1">${notice?`<div class="notice wrap" role="status">${esc(notice)}</div>`:''}${content}</main>`+footer();mountWelcome(!offline&&page==='home');if(!offline&&page==='shop')updateResults();if(!offline&&page==='checkout'&&cart.length)loadQuote(myToken);if(page==='admin')adminPage(myToken);if(page==='order')orderPage(route.id,myToken);if(page==='account')accountPage(myToken);if(focus)$('#main').focus({preventScroll:true})}
async function action(e){const b=e.target.closest('[data-action]');if(!b)return;let a=b.dataset.action;if(a==='banner'){safeStorage(sessionStorage,'riwaq-banner','1');b.parentElement.remove()}if(a==='lang'){lang=lang==='ar'?'en':'ar';safeStorage(localStorage,'riwaq-lang',lang);render()}if(a==='reload')await boot();if(a==='reset-filters'){location.hash=shopUrl(route.id);route=parseRoute(shopUrl(route.id));render()}if(a==='weight'||a==='grind'){const key=a==='weight'?'weight':'grind',value=+b.dataset.value;selected[key]=value;selected.qty=1;render();document.querySelector(`[data-action="${a}"][data-value="${value}"]`)?.focus()}if(a==='add'){try{selected.qty=quantity(Number($('#product-qty').value));let p=products.find(p=>p.id===b.dataset.id),v=variant(p);if(!v)throw new Error('UNKNOWN_VARIANT');cart=canonicalLines([...cart,{variant_id:v.id,qty:selected.qty}],products);save();render();toast(t('أضيفت للسلة.','Added to bag.'),['#/cart',t('عرض السلة','View bag')])}catch(e){$('#qty-error').textContent=errorText(e);toast(errorText(e))}}if(a==='remove'){cart.splice(+b.dataset.index,1);save();render()}if(a==='quiz'){quizState={step:0,answers:[]};drawQuiz();if(!$('#quiz').open)$('#quiz').showModal()}if(a==='quiz-close')$('#quiz').close();if(a==='quiz-answer'){quizState.answers.push(b.dataset.value);quizState.step++;drawQuiz()}if(a==='admin-refresh'){await refreshCatalog();render()}if(a==='event'){b.disabled=true;try{await api('/api/admin/sandbox-event',{method:'POST',body:{order_id:b.dataset.id,event_id:randomId(),kind:b.dataset.kind}});await refreshCatalog();render()}catch(e){toast(errorText(e));b.disabled=false}}if(a==='fill-demo'){const f=$('#checkout-form'),demo={name:t('سارة العتيبي','Sara Alotaibi'),email:'sara.demo@example.com',phone:'0551234567',city:t('الرياض','Riyadh'),address:t('حي العليا، شارع التحلية','Olaya District, Tahlia St.'),postal:'12241'};for(const[k,v]of Object.entries(demo)){f.elements[k].value=v;f.elements[k].removeAttribute('aria-invalid');$('#'+k+'-error').textContent=''}$('#place-order').focus()}
if(a==='sandbox-pay'){document.querySelectorAll('[data-action=sandbox-pay]').forEach(x=>x.disabled=true);let label=b.textContent;b.textContent=t('جاري معالجة الدفع التجريبي...','Processing sandbox payment...');try{await new Promise(r=>setTimeout(r,700));await api('/api/orders/'+encodeURIComponent(route.id)+'/sandbox-pay',{method:'POST',body:{order_token:orderToken(route.id),outcome:b.dataset.outcome,event_id:randomId()}});await refreshCatalog();render();window.scrollTo(0,0)}catch(e){toast(errorText(e));b.textContent=label;document.querySelectorAll('[data-action=sandbox-pay]').forEach(x=>x.disabled=false)}}
if(a==='cancel-order'){if(!confirm(t('هل تريد إلغاء هذا الطلب التجريبي؟','Cancel this demo order?')))return;b.disabled=true;try{await api('/api/orders/'+encodeURIComponent(route.id)+'/cancel',{method:'POST',body:{order_token:orderToken(route.id)}});await refreshCatalog();orderPage(route.id,token)}catch(e){toast(errorText(e));b.disabled=false}}if(a==='retry-order'){await refreshCatalog();try{cart=canonicalLines(lastOrder.items,products);save();location.hash='/checkout'}catch(e){toast(errorText(e))}}if(a==='refresh-order')orderPage(route.id,token)}
document.addEventListener('click',e=>{action(e).catch(e=>toast(errorText(e)))});
document.addEventListener('input',e=>{if(e.target.matches('[data-filter=q]')){route.filters.q=e.target.value;history.replaceState(null,'',shopUrl(route.id,route.filters));updateResults()}});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.filter&&el.dataset.filter!=='q'){route.filters[el.dataset.filter]=el.value;history.replaceState(null,'',shopUrl(route.id,route.filters));updateResults()}if(el.dataset.cart){const i=+el.dataset.index,l=cart[i],{p,v}=findVariant(l.variant_id),next=cart.map(l=>({...l}));try{if(el.dataset.cart==='qty')next[i].qty=quantity(Number(el.value));else next[i].variant_id=variantId(p.id,el.dataset.cart==='weight'?+el.value:v.weight,el.dataset.cart==='grind'?+el.value:v.grind);cart=canonicalLines(next,products);save();render()}catch(e){render();toast(errorText(e))}}});
document.addEventListener('submit',async e=>{const f=e.target;if(!f.matches('#checkout-form,#create-product,.product-editor'))return;e.preventDefault();if(f.id==='checkout-form'){await placeOrder(f);return}if(!f.reportValidity())return;let submit=f.querySelector('button[type=submit],button:not([type])');submit.disabled=true;try{let d=new FormData(f);if(f.id==='create-product'){await api('/api/admin/products',{method:'POST',body:{id:d.get('id'),price:Math.round(Number(d.get('price'))*100),data:{ar:d.get('ar'),en:d.get('en'),cat:d.get('cat'),color:'#637c7d',taste:'متوازنة',tasteEn:'Balanced',brew:'ترشيح',brewEn:'Filter'}}})}else{let p=adminProducts.find(p=>p.id===f.dataset.id),data=Object.fromEntries(['ar','en','notes','notesEn','image'].map(k=>[k,d.get(k)])),inventory=[],variants=[];for(let key of new Set(p.variants.map(v=>v.inventory_id))){inventory.push({id:key,stock:Number(d.get('stock:'+key))});for(let v of p.variants.filter(v=>v.inventory_id===key))variants.push({id:v.id,price:Math.round(Number(d.get('price:'+key))*100),active:v.active})}await api('/api/admin/products/'+encodeURIComponent(p.id),{method:'PATCH',body:{version:Number(f.dataset.version),data,active:d.has('active'),inventory,variants}})}await refreshCatalog();render();toast(t('تم الحفظ على الخادم.','Saved on server.'))}catch(e){toast(errorText(e));let p=f.querySelector('.error');if(p)p.textContent=errorText(e);submit.disabled=false}});
window.addEventListener('hashchange',()=>{selected={weight:250,grind:0,qty:1};let r=parseRoute(location.hash);if(r.page==='product'){let q=new URLSearchParams(location.hash.split('?')[1]||'');if(['250','500','1000'].includes(q.get('weight')))selected.weight=+q.get('weight')}notice='';render({focus:true});window.scrollTo(0,0)});
window.addEventListener('storage',e=>{if(e.key==='riwaq-cart'){synchronize();render()}});
async function boot(){try{await refreshCatalog();try{me=await api('/api/me')}catch{me={admin:false}}let r=parseRoute(location.hash);if(r.page==='product'){let q=new URLSearchParams(location.hash.split('?')[1]||'');if(['250','500','1000'].includes(q.get('weight')))selected.weight=+q.get('weight')}render()}catch(e){offline=true;render()}}
boot();
